// Los calendarios por salon del libro del equipo, leidos como los escriben.
//
// POR QUE EXISTE. La otra rama de este mismo workflow lee la pestana
// `Reservas`, que es una tabla hecha para la maquina. Pero el equipo no vende
// ahi: vende en el calendario de cada salon -- `CIUDAD JARDIN`, `MUNDO FOTO`,
// `AV 3 NTE`, `GRANADA GOLD 2026`... -- que es donde lleva la cuenta desde
// siempre. Hasta el 2026-09-02 eso entraba a la base UNA vez, a mano, con la
// migracion 20260901000000. Desde entonces, cada venta nueva que una persona
// anotaba en su calendario era invisible para el agente: la fecha seguia
// libre, y podia confirmarsela y apartarsela a otro cliente.
//
// Esta rama la mira cada quince minutos. No le pide al equipo que cambie de
// costumbre, que es la unica forma de que esto funcione de verdad.
//
// AQUI NO SE DECIDE NADA DE LA AGENDA. Igual que en `Leer Filas`: esto lee
// celdas y resuelve fechas; quien decide es `fn_sincronizar_agenda_desde_hoja`.
// Lo que no se entiende viaja con un `motivo` en vez de tirarse.
//
// GRANADA. Las pestanas `GRANADA 2026`, `GRANADA 2027` y `GRANADA` NO se leen:
// son del salon que el cliente mando ignorar ("es de una administracion
// diferente", 2026-09-02, ratificado el mismo dia). El unico Granada que se
// sincroniza es el Gold. Y si una fila de un maestro dice "GRANADA" a secas,
// la base la rechaza con su motivo -- no la resuelve al Gold por parecido.

// Las once pestanas de salon que SI son nuestras. El nombre de la pestana
// viaja como nombre de sede: quien lo traduce al catalogo es `sedes_alias`, en
// la base, para que los nombres del equipo vivan en un solo sitio.
const CALENDARIOS = ['MUNDO FOTO', 'AV 3 NTE', 'CIUDAD JARDIN', 'GRANADA GOLD 2026',
                     'GRANDA GOLD 2027', 'LAS PILAS', 'CASA 4', 'CASA 5', 'CASA 74',
                     'ORQUIDEORAMA 1', 'H. TALISMAN'];

// Los maestros llevan otra forma: la sede va DENTRO de la fila, en la columna
// C. Y llevan filas que los calendarios por salon no tienen, asi que no
// sobran: se leen los dos y lo repetido vuelve como "ya estaba".
//
// Se reconocen por el nombre -- cuatro digitos, el ano -- y no por una lista:
// el dia que el equipo abra la pestana del ano que viene, esta rama la lee
// sola. Lo que sigue haciendo falta es meter el rango nuevo en la URL del nodo
// de arriba, y de eso avisa `auditar-fechas-excel.js`.
const esMaestro = (nombre) => /^[0-9]{4}$/.test(nombre.trim());

// La pestana donde se escribe lo que no se pudo leer. Se lee tambien, para no
// reescribirla cuando no ha cambiado nada.
const REVISION = 'Revisar';

const DIAS = { DOMINGO: 0, LUNES: 1, MARTES: 2, MIERCOLES: 3, JUEVES: 4, VIERNES: 5, SABADO: 6 };
const MESES = { ENERO: 1, FEBRERO: 2, MARZO: 3, ABRIL: 4, MAYO: 5, JUNIO: 6, JULIO: 7,
                AGOSTO: 8, SEPTIEMBRE: 9, OCTUBRE: 10, NOVIEMBRE: 11, DICIEMBRE: 12 };

const sinTildes = (s) => String(s === null || s === undefined ? '' : s)
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim();

const dosDigitos = (n) => String(n).padStart(2, '0');

// ---------------------------------------------------------------------------
// EL ANO DE ESTAS CELDAS NO ES DE FIAR, Y EL DIA DE LA SEMANA SI
// ---------------------------------------------------------------------------
// El libro nacio como `2025.xlsx` y se reutilizo para 2026: media hoja
// conserva el ano viejo. Lo que dice la verdad es el dia de la semana, que es
// como lo lee una persona. `2025-12-04 VIERNES` es el 4 de diciembre de 2026,
// que es el que cae en viernes. Asi se cargaron las 113 de la migracion
// 20260901000000 y asi hay que leer cualquier fecha de estas pestanas.
//
// La ventana va del ano pasado a tres adelante. Con el dia de la semana fijo,
// dentro de una ventana de cinco anos cae UNO solo -- el mismo dia de la
// semana vuelve a los 5, 6 u 11 anos -- asi que no hay que elegir. Si cayeran
// dos, se rechaza: adivinar aqui es dar por libre una fecha vendida.
function resolverFecha(celdaFecha, celdaDia, mesEnCurso, hoy, anoFijo) {
  // Una fecha DE VERDAD llega como numero de serie de Sheets y no tiene
  // ninguna ambiguedad: se cree tal cual, sin mirar el dia de la semana. Es lo
  // que van a escribir de aqui en adelante los que tecleen en la hoja nueva.
  if (typeof celdaFecha === 'number' && Number.isFinite(celdaFecha)) {
    const ms = Date.UTC(1899, 11, 30) + Math.round(celdaFecha) * 86400000;
    return { fecha: new Date(ms).toISOString().slice(0, 10) };
  }

  const texto = sinTildes(celdaFecha);
  const nombreDia = Object.keys(DIAS).find((d) => sinTildes(celdaDia).startsWith(d)) ||
                    Object.keys(DIAS).find((d) => texto.includes(d));
  const objetivo = nombreDia === undefined ? null : DIAS[nombreDia];

  let anoCelda = null; let mes = null; let diaMes = null;
  const iso = String(celdaFecha === null || celdaFecha === undefined ? '' : celdaFecha).trim()
    .match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (iso) { anoCelda = +iso[1]; mes = +iso[2]; diaMes = +iso[3]; }
  else {
    // "7 diciemnre", "4 de diciembre", "MARZO 20": el mes va tecleado a mano y
    // a veces con errata, asi que se compara por sus cuatro primeras letras.
    const conMes = texto.match(/(\d{1,2})\s*(?:DE\s*)?([A-Z]{4,})/) ||
                   texto.match(/([A-Z]{4,})\s*(\d{1,2})/);
    if (conMes) {
      const numero = /^\d/.test(conMes[1]) ? conMes[1] : conMes[2];
      const palabra = /^\d/.test(conMes[1]) ? conMes[2] : conMes[1];
      const llave = Object.keys(MESES).find((k) => k.slice(0, 4) === palabra.slice(0, 4));
      if (llave) { diaMes = +numero; mes = MESES[llave]; }
    }
    // "SABADO 22": el mes es el titular de la seccion, en la columna A.
    if (!mes) {
      const soloDia = texto.match(/(?:^|[^\d])(\d{1,2})(?:[^\d]|$)/);
      if (soloDia && nombreDia !== undefined && mesEnCurso) { diaMes = +soloDia[1]; mes = mesEnCurso; }
    }
  }
  if (!mes || !diaMes || diaMes > 31) return { motivo: `no entiendo la fecha "${celdaFecha}"` };

  // Con ano en la celda y sin dia de la semana no hay nada que resolver.
  if (anoCelda !== null && objetivo === null) {
    return { fecha: `${anoCelda}-${dosDigitos(mes)}-${dosDigitos(diaMes)}` };
  }

  // En los maestros el ano NO se busca: lo dice el nombre de la pestana. La
  // 2027 es de 2027, y si una fila de ahi lleva mal el dia de la semana, lo
  // que hay que hacer es preguntarlo -- no saltar dos anos hasta que cuadre.
  // Paso de verdad: `2027!B53 "SABADO 8"` de SEPTIEMBRE acababa en 2029,
  // apartando un sabado de 2029 que nadie ha vendido.
  const desde = anoFijo || (hoy.getUTCFullYear() - 1);
  const hasta = anoFijo || (desde + 4);
  const candidatos = [];
  for (let a = desde; a <= hasta; a++) {
    const f = new Date(Date.UTC(a, mes - 1, diaMes));
    if (f.getUTCMonth() !== mes - 1) continue;          // 31 de febrero y parecidos
    if (objetivo === null || f.getUTCDay() === objetivo) candidatos.push(f);
  }
  if (!candidatos.length) {
    return { motivo: `"${celdaFecha}" no cae en ${nombreDia || celdaDia} en ` +
                     (anoFijo ? `${anoFijo}: revisa el día de la semana o el año`
                              : `ningún año entre ${desde} y ${hasta}: revisa el día de la semana`) };
  }
  if (candidatos.length > 1) {
    return { motivo: `no sé de qué año es "${celdaFecha}": podría ser ` +
                     candidatos.map((f) => f.toISOString().slice(0, 10)).join(' o ') };
  }
  return { fecha: candidatos[0].toISOString().slice(0, 10) };
}

// Una fila esta vendida si la columna del nombre trae algo. "LEY SECA",
// "VOTACIONES" y "OCUPADO" tambien: son dias que el equipo se bloquea a si
// mismo, y para el agente valen lo mismo que una venta.
const estaVendida = (nombre) => {
  const t = sinTildes(nombre);
  return t !== '' && !/^[-.X\s]+$/.test(t);
};

// ---------------------------------------------------------------------------
const respuesta = $input.first().json;
const rangos = respuesta.valueRanges || [];

// Se casa por el nombre que devuelve Sheets, no por la posicion: si un dia
// alguien quita un rango de la URL, esto se entera y lo dice, en vez de leer
// una pestana creyendo que es otra.
const porPestana = new Map();
for (const r of rangos) {
  const nombre = String(r.range || '').split('!')[0].replace(/^'|'$/g, '');
  porPestana.set(nombre, r.values || []);
}

const hoy = new Date();
const filas = [];
const revisar = [];
const faltan = [];

function leerCalendario(pestana, conSedeDentro, anoFijo) {
  const valores = porPestana.get(pestana);
  if (valores === undefined) { faltan.push(pestana); return; }

  let mesEnCurso = null;
  for (let i = 0; i < valores.length; i++) {
    const f = valores[i] || [];
    const cel = (n) => (f[n] === undefined || f[n] === null ? '' : f[n]);

    const titular = MESES[sinTildes(cel(0))];
    if (titular) mesEnCurso = titular;

    const celdaFecha = cel(1);
    const cliente = String(cel(3)).trim();
    // En los maestros la sede va en la columna C; en los calendarios de salon
    // la columna C es el dia de la semana y la sede es la pestana.
    const sede = conSedeDentro ? String(cel(2)).trim() : pestana;
    const celdaDia = conSedeDentro ? '' : cel(2);

    if (celdaFecha === '' || sinTildes(celdaFecha) === 'FECHA') continue;
    if (!estaVendida(cliente)) continue;

    const r = resolverFecha(celdaFecha, celdaDia, mesEnCurso, hoy, anoFijo);
    const item = {
      fila: filas.length,          // el indice aqui dentro: es como vuelve la respuesta
      pestana,
      fila_hoja: i + 1,
      celda: String(celdaFecha),
      sede,
      cliente,
      telefono: String(cel(4) || '').trim(),
      fecha: r.fecha || null,
      cancelar: false,             // estas pestanas no liberan fechas: ver abajo
      motivo: r.motivo || (sede ? null : 'la fila no dice en qué salón es'),
    };
    filas.push(item);
  }
}

for (const p of CALENDARIOS) leerCalendario(p, false);
for (const p of porPestana.keys()) if (esMaestro(p)) leerCalendario(p, true, Number(p.trim()));

// Lo que hay AHORA en la pestana de revision, para poder no reescribirla si no
// ha cambiado nada. Va en el mismo viaje que todo lo demas.
const revisionActual = porPestana.get(REVISION) || [];

// BORRAR NO LIBERA, TAMPOCO AQUI. Ninguna fila de estas pestanas puede soltar
// una fecha: `cancelar` va siempre en false. Si alguien borra un nombre de su
// calendario -- o filtra, o deshace de mas -- la fecha sigue apartada. Para
// soltarla hay que decirlo en la pestana `Reservas`, con la columna
// `cancelada`, que es donde queda el rastro de quien la solto.

if (!filas.length) return [];

return [{
  json: {
    filas,
    revision_actual: revisionActual,
    pestanas_leidas: rangos.length,
    pestanas_que_faltan: faltan,
    vendidas: filas.length,
  },
}];

// La pestana `Revisar`: las filas del libro que la sincronizacion NO pudo
// meter en la agenda, escritas donde alguien las vea.
//
// POR QUE UNA PESTANA APARTE. La rama de `Reservas` escribe el resultado de
// cada fila al lado de la fila, en su columna `sincronizado`. Aqui no se puede:
// los calendarios del equipo son SU documento -- una copia fiel del libro que
// llevan -- y meterles una columna de la maquina seria cambiarles el papel
// debajo de la mano. Asi que el rechazo se recoge en una lista aparte.
//
// Y tiene que estar en la hoja, no en los logs de n8n: nadie mira los logs. Si
// el rechazo no esta aqui, no esta en ninguna parte -- y una fila rechazada es
// una fecha vendida que el agente sigue viendo libre.
//
// LO QUE NO SALE. Las fechas que ya pasaron. Son cientos -- el libro arranca
// en enero de 2025 -- y no hay nada que proteger en ellas: el propio agente
// rechaza una fecha pasada antes de mirar la agenda. Si salieran, la lista
// util quedaria enterrada debajo de ellas, que es la forma mas segura de que
// nadie la lea.
//
// ES ESTABLE A PROPOSITO. Se calcula solo con el estado de ahora, sin fechas
// ni horas dentro, y se compara con lo que ya hay en la pestana: dos corridas
// seguidas sin novedad no escriben ni una celda. Sin eso, la hoja acumularia
// una version nueva cada quince minutos.

const ENCABEZADO = ['pestaña', 'fila', 'celda', 'salón', 'cliente', 'qué pasó'];

// Lo que merece que alguien lo mire.
//   rechazada  no se pudo leer: fecha imposible, salón que no existe
//   choque     el bot y una persona tienen la misma fecha
//   omitida    solo cuando NO es una fecha pasada: ahí está el "este salón no
//              lo manejamos", que conviene ver una vez.
const salePorResultado = (r) =>
  r.resultado === 'rechazada' ||
  r.resultado === 'choque' ||
  (r.resultado === 'omitida' && r.detalle !== 'la fecha ya pasó');

const entrada = $('Leer Calendarios en Filas').first().json;
const porIndice = new Map(entrada.filas.map((f) => [f.fila, f]));

const lineas = [];
for (const item of $('Sincronizar Calendarios').all()) {
  const r = item.json;
  if (!salePorResultado(r)) continue;
  const f = porIndice.get(r.fila);
  if (!f) continue;                       // el indice viaja de ida y vuelta: no deberia faltar
  lineas.push([f.pestana, f.fila_hoja, f.celda, f.sede || '', f.cliente || '', r.detalle || '']);
}

// Una pestana que la sincronizacion no encontro es mas grave que cualquier
// fila: significa que un salon entero se esta quedando fuera. Va primero.
for (const p of (entrada.pestanas_que_faltan || [])) {
  lineas.unshift([p, '', '', '', '',
    'no pude leer esta pestaña: ¿la renombraron? Mientras tanto, ese salón no se está sincronizando']);
}

// Orden fijo: si el contenido no cambia, la lista tampoco.
lineas.sort((a, b) => String(a[0]).localeCompare(String(b[0])) || (Number(a[1]) || 0) - (Number(b[1]) || 0));

// ¿Cambió algo respecto de lo que ya está escrito? Se compara celda a celda,
// contra lo que se leyó de A2 hacia abajo en el mismo viaje.
const actual = (entrada.revision_actual || []).filter((f) => (f || []).some((c) => String(c || '').trim() !== ''));
const mismo = actual.length === lineas.length &&
  lineas.every((l, i) => l.every((c, j) => String(c) === String((actual[i] || [])[j] === undefined ? '' : (actual[i] || [])[j])));

if (mismo) return [];

// Se escribe desde A2 y se rellena con filas vacías hasta cubrir lo que había
// antes: sin eso, una lista que se acorta dejaría abajo los restos de la
// anterior -- avisos ya resueltos que alguien volvería a perseguir.
const ancho = ENCABEZADO.length;
const vacia = new Array(ancho).fill('');
const valores = lineas.slice();
while (valores.length < actual.length) valores.push(vacia.slice());

return [{
  json: {
    data: [{ range: `Revisar!A2:F${1 + Math.max(valores.length, 1)}`,
             values: valores.length ? valores : [vacia.slice()] }],
    pendientes: lineas.length,
  },
}];
